const d = await deepwiki.read_wiki_contents({repoName:"modelcontextprotocol/servers"});
const lines = d.split("\n");
let cur=null, pages=[], inFence=false, fenceMermaid=false;
for(const l of lines){
 if(l.startsWith("# Page: ")){cur={t:l.slice(8),n:0,h:null};pages.push(cur);inFence=false;continue;}
 if(!cur)continue;
 if(l.trimStart().startsWith("```")){
   if(!inFence){inFence=true;fenceMermaid=/^\s*```\s*mermaid/.test(l); if(!fenceMermaid)cur.n++;}
   else inFence=false;
   continue;
 }
 if(!inFence && l.startsWith("## ") && !cur.h) cur.h=l;
}
pages.sort((a,b)=>b.n-a.n);
return pages.slice(0,3);

const d = await deepwiki.read_wiki_contents({repoName:"modelcontextprotocol/servers"});
const lines = d.split("\n");
let cur=null, pages=[];
for(const l of lines){
 if(l.startsWith("# Page: ")){cur={title:l.slice(8).trim(),count:0,open:false,h2:null};pages.push(cur);continue;}
 if(!cur)continue;
 if(l.trimStart().startsWith("```")){
   if(!cur.open){cur.open=true;cur.lang=l.trim().slice(3).trim();}
   else{cur.open=false; if(cur.lang!=="mermaid")cur.count++;}
 }
 if(!cur.open && l.startsWith("## ") && !cur.h2) cur.h2=l;
}
pages.sort((a,b)=>b.count-a.count);
return JSON.stringify(pages.slice(0,3));

