const d = await deepwiki.read_wiki_contents({repoName:"modelcontextprotocol/servers"});
const lines = d.split("\n");
let pages=[],cur=null,open=false,lang="";
for(const l of lines){
 if(l.startsWith("# Page: ")){cur={t:l.slice(8),n:0,h:null,lines:[]};pages.push(cur);open=false;continue;}
 if(!cur)continue;
 const m=l.match(/^\s*```(\w*)/);
 if(m){ if(!open){open=true;lang=m[1].toLowerCase();} else {open=false; if(lang!=="mermaid")cur.n++;} continue;}
 if(!open && cur.h===null && l.startsWith("## "))cur.h=l;
}
pages.sort((a,b)=>b.n-a.n);
return JSON.stringify(pages.slice(0,4).map(p=>[p.t,p.n,p.h]));

const t = await deepwiki.read_wiki_contents({repoName:"modelcontextprotocol/servers"});
const lines = t.split("\n");
let pages=[],cur=null;
for(const l of lines){ if(l.startsWith("# Page: ")){cur={title:l.slice(8),lines:[]};pages.push(cur);} else if(cur)cur.lines.push(l);}
let res=pages.map(p=>{let n=0,open=false,lang="";for(const l of p.lines){const m=l.match(/^\s*```(\w*)/);if(m){if(!open){open=true;lang=m[1];}else{open=false;if(lang!=="mermaid")n++;}}}
const h=p.lines.find(l=>l.startsWith("## "));return {t:p.title,n,h};});
res.sort((a,b)=>b.n-a.n);
return JSON.stringify(res.slice(0,4));
